+      // Check fading (energy depleted)
+      if (blob.energy <= 0 && !deadIds.has(blob.id)) {
+        deadIds.add(blob.id);
+        this.releaseClaimedFruit(blob);
+        this.effects.push({
+          id: this.nextEffectId++,
+          type: 'fade_puff',
+          x: blob.x,
+          y: 8,
+          z: blob.z,
+          color: blob.group === 'blue' ? '#93C5FD' : '#FCA5A5',
+          age: 0,
+          duration: 0.7,
+          radius: 13,
+        });
+      }
