    for (let s = 0; s < 100; s++) {
      for (let k = 0; k < 30; k++) sim.step(1/30);
      if (s % 5 === 0) {
        const c = sim.getPopulationCounts();
        samples.push(`${s+1}s:F${c.fruit}/B${c.blue}/R${c.red}`);
      }
    }
    const summary = sim.getRunSummary();
    console.log(`\n=== ${id} (${preset.name}) ===`);
