import("./src/simulation/presets.ts").then(async ({ PRESETS }) => {
  const { GardenSimulation } = await import("./src/simulation/engine.ts");
  for (const [id, preset] of Object.entries(PRESETS)) {
    const sim = new GardenSimulation(preset.config);
    const samples = [];
    for (let s = 0; s < 100; s++) {
      for (let k = 0; k < 30; k++) sim.step(1/30);
      if (s % 5 === 0) {
        const c = sim.getPopulationCounts();
        samples.push(`${s+1}s:F${c.fruit}/B${c.blue}/R${c.red}`);
      }
    }
    const summary = sim.getRunSummary();
    console.log(`\n=== ${id} (${preset.name}) ===`);
    console.log(samples.join(" | "));
    console.log("Headline:", summary.headline, "| Waves:", summary.waveCount, "| Peaks B/R/F:", summary.peakBlue, summary.peakRed, summary.peakFruit);
  }
});
'

