        <div className="grid grid-cols-5 gap-1 bg-[#F4F0E6] p-1 rounded-xl border border-[#E5DEC9] mb-3 text-[11px] font-semibold">
          {(
            [
              { id: 'all', label: 'All' },
              { id: 'fruit', label: 'Fruit' },
              { id: 'blue', label: 'Blue' },
              { id: 'red', label: 'Red' },
              { id: 'world', label: 'World' },
