                min={2}
                max={50}
                step={1}
                unit=" blobs"
                accentClass="accent-amber-600"
                onChange={(v) => onUpdateConfig({ startingBlue: v }, true)}
              />
              <SliderRow
                label="Starting Red Blobs"
                value={config.startingRed}
                min={0}
                max={40}
                step={1}
                unit=" blobs"
                accentClass="accent-amber-600"
                onChange={(v) => onUpdateConfig({ startingRed: v }, true)}
              />

