                type="button"
                onClick={onReset}
                className="w-full mt-1 flex items-center justify-center gap-1.5 py-1.5 rounded-lg bg-white hover:bg-[#F4F0E6] text-xs font-semibold text-[#334139] border border-[#D8D0BC] transition"
              >
